import { useRef, useState } from "react"
import { File as FileIcon, Trash2, X } from "lucide-react"
import { Alert } from "@atlas/ui-web/compositions/Alert/Alert"
import { ListItem, ListItemMedia, ListItemContent, ListItemTitle, ListItemDescription, ListItemActions } from "@atlas/ui-web/compositions/ListItem/ListItem"
import { Badge } from "@atlas/ui-web/primitives/Badge/Badge"
import { Button } from "@atlas/ui-web/primitives/Button/Button"
import { Progress } from "@atlas/ui-web/primitives/Progress/Progress"

type Status = "uploading" | "done" | "failed"
type Item = { id: number; file: File; status: Status; progress: number; retryable: boolean; reason?: string; retrying?: boolean }

const MAX_BYTES = 10 * 1024 * 1024
const muted = { fontSize: "var(--atlas-text-body-sm)", color: "var(--atlas-foreground-muted)" }
const visuallyHidden = { position: "absolute", width: 1, height: 1, overflow: "hidden", clipPath: "inset(50%)" } as const

// `send` is the app's upload call: it reports progress 0-100 and rejects with { retryable: false } when the file itself is refused.
export function FileUpload({ send }: { send: (file: File, onProgress: (pct: number) => void) => Promise<void> }) {
  const input = useRef<HTMLInputElement>(null)
  const next = useRef(0)
  const [items, setItems] = useState<Item[]>([])
  const [over, setOver] = useState(false)
  const [rejected, setRejected] = useState<string[]>([])
  const [live, setLive] = useState("")

  const patch = (id: number, change: Partial<Item>) =>
    setItems((all) => all.map((i) => (i.id === id ? { ...i, ...change } : i)))

  async function run(id: number, file: File) {
    patch(id, { status: "uploading", progress: 0, retrying: false })
    try {
      await send(file, (progress) => patch(id, { progress }))
      patch(id, { status: "done", progress: 100 })
      setLive(`${file.name} uploaded`)
    } catch (e) {
      // The request failed (retry) or the file did (remove): the same file would fail again.
      const retryable = (e as { retryable?: boolean })?.retryable !== false
      patch(id, {
        status: "failed",
        retryable,
        reason: retryable ? "Upload failed. Check your connection and try again." : "The server rejected this file. Remove it and choose another.",
      })
      setLive(`${file.name} failed`)
    }
  }

  function add(list: FileList | null) {
    if (!list) return
    const refused: string[] = []
    for (const file of Array.from(list)) {
      // Check the limits first: never start an upload that is already ruled out.
      if (file.size > MAX_BYTES) { refused.push(`${file.name} is larger than 10 MB.`); continue }
      const id = next.current++
      setItems((all) => [...all, { id, file, status: "uploading", progress: 0, retryable: true }])
      void run(id, file)
    }
    setRejected(refused)
  }

  const failed = items.filter((i) => i.status === "failed")
  const retryable = failed.filter((i) => i.retryable)

  return (
    <div style={{ display: "grid", gap: "var(--atlas-spacing-4)" }}>
      <div
        onDragOver={(e) => { e.preventDefault(); setOver(true) }}
        onDragLeave={() => setOver(false)}
        onDrop={(e) => { e.preventDefault(); setOver(false); add(e.dataTransfer.files) }}
        style={{
          display: "grid", justifyItems: "center", gap: "var(--atlas-spacing-3)", padding: "var(--atlas-spacing-6)",
          border: `var(--atlas-border-width-1) dashed ${over ? "var(--atlas-primary)" : "var(--atlas-border-strong)"}`,
          borderRadius: "var(--atlas-radius-base)",
          background: over ? "var(--atlas-background-muted)" : "var(--atlas-background-subtle)",
        }}
      >
        <span style={{ fontSize: "var(--atlas-text-body)" }}>Drop files here, or</span>
        <Button variant="outline" onClick={() => input.current?.click()}>Choose files</Button>
        <span style={muted}>PDF, PNG or JPG, up to 10 MB each.</span>
        {/* The Button is the keyboard path; the input stays out of the tab order. */}
        <input ref={input} type="file" multiple accept=".pdf,.png,.jpg,.jpeg" tabIndex={-1} aria-hidden="true" style={visuallyHidden}
          onChange={(e) => { add(e.target.files); e.target.value = "" }} />
      </div>

      {rejected.length > 0 && (
        <Alert variant="danger" title="Some files were not added" description={rejected.join(" ")} />
      )}

      {failed.length > 1 && retryable.length > 0 && (
        <Alert variant="danger" title={`${failed.length} files failed to upload`}
          description="Your other files were not affected. Try the failed ones again."
          actions={<Button size="sm" variant="outline" onClick={() => retryable.forEach((i) => void run(i.id, i.file))}>Retry all</Button>} />
      )}

      <ul style={{ display: "grid", gap: "var(--atlas-spacing-3)", listStyle: "none", margin: 0, padding: 0 }}>
        {items.map((i) => (
          <ListItem as="li" key={i.id} variant="outline">
            <ListItemMedia type="icon" decorative><FileIcon /></ListItemMedia>
            <ListItemContent>
              <ListItemTitle>{i.file.name}</ListItemTitle>
              {i.status === "uploading" ? (
                <Progress value={i.progress} valueLabel={`${i.progress}%`} aria-label={`Uploading ${i.file.name}`} aria-valuetext={`${i.progress} percent`} />
              ) : (
                <ListItemDescription>{i.status === "done" ? "Uploaded" : i.reason}</ListItemDescription>
              )}
            </ListItemContent>
            <ListItemActions>
              {i.status === "done" && <Badge variant="success" size="sm">Done</Badge>}
              {i.status === "failed" && <Badge variant="danger" size="sm">Failed</Badge>}
              {i.status === "failed" && i.retryable && (
                <Button size="sm" variant="outline" loading={i.retrying}
                  onClick={() => { patch(i.id, { retrying: true }); void run(i.id, i.file) }}>Retry</Button>
              )}
              <Button iconOnly size="sm" variant="ghost"
                aria-label={`${i.status === "uploading" ? "Cancel" : "Remove"} ${i.file.name}`}
                onClick={() => setItems((all) => all.filter((x) => x.id !== i.id))}>
                {i.status === "uploading" ? <X /> : <Trash2 />}
              </Button>
            </ListItemActions>
          </ListItem>
        ))}
      </ul>

      <div role="status" aria-live="polite" style={visuallyHidden}>{live}</div>
    </div>
  )
}

